import{_ as s,o as a,c as i,a3 as n}from"./chunks/framework.Crt1tuW8.js";const t="/BD1A26/assets/creation-bd-gui.7SvB3ztl.png",o="/BD1A26/assets/connexion-gui.ym0NepWy.png",r="/BD1A26/assets/regenerer.DEy1g7lR.png",m=JSON.parse('{"title":"01 — Créer une base de données","description":"","frontmatter":{"title":"01 — Créer une base de données","aside":false},"headers":[],"relativePath":"modules/02-ddl-base/01-create-database.md","filePath":"modules/02-ddl-base/01-create-database.md"}'),l={name:"modules/02-ddl-base/01-create-database.md"};function d(c,e,u,p,h,b){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="_01-—-creer-une-base-de-donnees" tabindex="-1">01 — Créer une base de données <a class="header-anchor" href="#_01-—-creer-une-base-de-donnees" aria-label="Permalink to &quot;01 — Créer une base de données&quot;">​</a></h1><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Comprendre qu’une <strong>base de données MariaDB</strong> est un <strong>contenant logique de haut niveau</strong>, utilisé pour regrouper les tables d’un même travail ou projet, avant même de contenir des données.</p><hr><h2 id="ddl-—-data-definition-language" tabindex="-1">DDL — Data Definition Language <a class="header-anchor" href="#ddl-—-data-definition-language" aria-label="Permalink to &quot;DDL — Data Definition Language&quot;">​</a></h2><p>Le <strong>DDL</strong> est la partie du langage SQL qui permet de <strong>définir et modifier la structure d’une base de données</strong> (BDs, tables, colonnes, contraintes).</p><hr><h2 id="organisation-logique-dans-mariadb" tabindex="-1">Organisation logique dans MariaDB <a class="header-anchor" href="#organisation-logique-dans-mariadb" aria-label="Permalink to &quot;Organisation logique dans MariaDB&quot;">​</a></h2><p>Dans MariaDB, les éléments sont organisés de la façon suivante :</p><ul><li>Serveur MariaDB <ul><li>Base de données <ul><li>Tables</li></ul></li></ul></li></ul><blockquote><p>Une table appartient directement à une <strong>base de données</strong>.</p></blockquote><hr><h2 id="role-d-une-base-de-donnees" tabindex="-1">Rôle d’une base de données <a class="header-anchor" href="#role-d-une-base-de-donnees" aria-label="Permalink to &quot;Rôle d’une base de données&quot;">​</a></h2><p>Une base de données permet de :</p><ul><li>isoler complètement les données d’un travail ou d’un projet</li><li>regrouper toutes les tables liées à un même contexte</li><li>appliquer des paramètres globaux (droits, encodage)</li></ul><hr><h2 id="base-de-donnees-ou-schema" tabindex="-1">Base de données ou schéma ? <a class="header-anchor" href="#base-de-donnees-ou-schema" aria-label="Permalink to &quot;Base de données ou schéma ?&quot;">​</a></h2><p>Dans certains SGBD (PostgreSQL, Oracle), un niveau supplémentaire appelé <strong>schéma</strong> s’insère entre la base de données et les tables.</p><p><strong>Ce niveau n’existe pas dans MariaDB.</strong> Pour MariaDB, les mots <em>base de données</em> et <em>schéma</em> désignent exactement la même chose.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tp_evenements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> schema</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tp_evenements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- fait rigoureusement la même chose</span></span></code></pre></div><blockquote><p>Ne soyez donc pas surpris de voir le mot <strong>Schema</strong> apparaître dans DBeaver ou dans les messages d’erreur : il s’agit de votre base de données.</p></blockquote><hr><h2 id="encodage-de-la-base-de-donnees" tabindex="-1">Encodage de la base de données <a class="header-anchor" href="#encodage-de-la-base-de-donnees" aria-label="Permalink to &quot;Encodage de la base de données&quot;">​</a></h2><p>Lors de la création d’une base de données, MariaDB lui associe un <strong>jeu de caractères</strong> (<em>character set</em>) et une <strong>règle de comparaison</strong> (<em>collation</em>).</p><ul><li>Le jeu de caractères détermine comment les caractères sont stockés</li><li>Il influence la gestion des accents et caractères spéciaux</li><li>Le jeu <strong><code>utf8mb4</code></strong> est celui à utiliser : c’est le seul qui stocke correctement <strong>tous</strong> les caractères Unicode (accents, mais aussi emojis)</li></ul><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4"><strong>Piège fréquent</strong><br> Dans MariaDB, le jeu de caractères nommé <code>utf8</code> est un « faux » UTF-8 limité à 3 octets par caractère. Utilisez toujours <code>utf8mb4</code>. </div><p><strong>Dans ce cours</strong></p><blockquote><p>Nous utilisons le jeu de caractères par défaut du serveur, configuré en <code>utf8mb4</code> lors de l’installation (voir le Lab 01).<br> Aucune configuration particulière n’est requise de votre part.</p></blockquote><p>Il est toutefois possible de le préciser explicitement :</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tp_evenements</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    character</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> utf8mb4;</span></span></code></pre></div><h2 id="convention-de-nommage" tabindex="-1">Convention de nommage <a class="header-anchor" href="#convention-de-nommage" aria-label="Permalink to &quot;Convention de nommage&quot;">​</a></h2><h3 id="bases-de-donnees" tabindex="-1">Bases de données <a class="header-anchor" href="#bases-de-donnees" aria-label="Permalink to &quot;Bases de données&quot;">​</a></h3><ul><li>minuscules</li><li>mots séparés par des underscores (<code>_</code>)</li><li>pas d’espaces ni d’accents</li><li>nom représentatif du travail</li></ul><p><strong>Exemples</strong></p><ul><li><code>tp_evenements</code></li><li><code>tp_gestion_clients</code></li><li><code>tp_suivi_projets</code></li></ul><hr><h2 id="creer-une-base-de-donnees" tabindex="-1">Créer une base de données <a class="header-anchor" href="#creer-une-base-de-donnees" aria-label="Permalink to &quot;Créer une base de données&quot;">​</a></h2><h3 id="instruction-create-database" tabindex="-1">Instruction <code>CREATE DATABASE</code> <a class="header-anchor" href="#instruction-create-database" aria-label="Permalink to &quot;Instruction \`CREATE DATABASE\`&quot;">​</a></h3><h4 id="syntaxe" tabindex="-1">Syntaxe <a class="header-anchor" href="#syntaxe" aria-label="Permalink to &quot;Syntaxe&quot;">​</a></h4><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> nom_base</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tp_evenements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h4 id="option-gui" tabindex="-1">Option GUI <a class="header-anchor" href="#option-gui" aria-label="Permalink to &quot;Option GUI&quot;">​</a></h4><img src="`+t+'" alt="Création BD GUI" class="img-bordered w-s"><h2 id="choisir-la-base-de-donnees-de-travail" tabindex="-1">Choisir la base de données de travail <a class="header-anchor" href="#choisir-la-base-de-donnees-de-travail" aria-label="Permalink to &quot;Choisir la base de données de travail&quot;">​</a></h2><p>Créer une base de données ne veut pas dire qu’on y travaille. Il faut ensuite indiquer à MariaDB <strong>dans quelle base</strong> les prochaines instructions doivent s’exécuter.</p><h3 id="instruction-use" tabindex="-1">Instruction <code>USE</code> <a class="header-anchor" href="#instruction-use" aria-label="Permalink to &quot;Instruction `USE`&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tp_evenements;</span></span></code></pre></div><p>À partir de ce moment, toutes les instructions (<code>create table</code>, <code>insert</code>, <code>select</code>…) s’appliquent à <code>tp_evenements</code>, et ce jusqu’à ce qu’on écrive un autre <code>use</code>.</p><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4"><strong>Erreur classique</strong><br><code>No database selected</code> : vous avez oublié le <code>use</code> au début de votre script. </div><blockquote><p>Bonne habitude : commencer <strong>tout script SQL</strong> par son <code>use</code>. Ainsi, le script reste correct même si quelqu’un d’autre l’exécute.</p></blockquote><h3 id="option-gui-1" tabindex="-1">Option GUI <a class="header-anchor" href="#option-gui-1" aria-label="Permalink to &quot;Option GUI&quot;">​</a></h3><p>La base de données active peut aussi être choisie dans la barre d’outils de DBeaver.</p><img src="'+o+'" alt="Connexion BD GUI" class="img-bordered w-s"><blockquote><p>Vous pouvez aussi définir la base de données dans laquelle vous travaillez comme <code>objet par défaut</code></p></blockquote><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4"> Le <code>use</code> écrit dans le script et la sélection dans DBeaver font la même chose. Pour vos travaux, écrivez toujours le <code>use</code> : votre script doit être complet à lui seul. </div><hr><h2 id="verifier-l-existence-des-bases-de-donnees" tabindex="-1">Vérifier l’existence des bases de données <a class="header-anchor" href="#verifier-l-existence-des-bases-de-donnees" aria-label="Permalink to &quot;Vérifier l’existence des bases de données&quot;">​</a></h2><h3 id="lister-les-bases-disponibles" tabindex="-1">Lister les bases disponibles <a class="header-anchor" href="#lister-les-bases-disponibles" aria-label="Permalink to &quot;Lister les bases disponibles&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span></code></pre></div><h3 id="savoir-dans-quelle-base-on-se-trouve" tabindex="-1">Savoir dans quelle base on se trouve <a class="header-anchor" href="#savoir-dans-quelle-base-on-se-trouve" aria-label="Permalink to &quot;Savoir dans quelle base on se trouve&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Vous pouvez également faire clic-droit et rafraîchir (F5)</p><img src="'+r+'" alt="Regénérer BD" class="img-bordered w-s">',62)])])}const k=s(l,[["render",d]]);export{m as __pageData,k as default};
